CREATE DATABASE IF NOT EXISTS aitourism CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE aitourism;

CREATE TABLE IF NOT EXISTS t_macau_catalog_poi (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    poi_code VARCHAR(64) NOT NULL,
    region VARCHAR(32) NOT NULL,
    category VARCHAR(32) NOT NULL,
    name_zh_hans VARCHAR(128) NOT NULL,
    name_zh_hant VARCHAR(128) NOT NULL,
    name_en VARCHAR(160) NOT NULL,
    name_pt VARCHAR(160) NOT NULL,
    description_zh_hans VARCHAR(500) NOT NULL DEFAULT '',
    description_zh_hant VARCHAR(500) NOT NULL DEFAULT '',
    description_en VARCHAR(500) NOT NULL DEFAULT '',
    description_pt VARCHAR(500) NOT NULL DEFAULT '',
    longitude DECIMAL(10,7) NOT NULL,
    latitude DECIMAL(10,7) NOT NULL,
    opening_hours VARCHAR(128) NOT NULL DEFAULT 'Refer to official source',
    accessibility_level VARCHAR(16) NOT NULL,
    source_organization VARCHAR(128) NOT NULL DEFAULT '澳门特别行政区政府旅游局',
    source_url VARCHAR(500) NOT NULL DEFAULT 'https://www.macaotourism.gov.mo/',
    source_published_at DATE NOT NULL,
    valid_until DATE NOT NULL,
    natural_merchant BOOLEAN DEFAULT FALSE NOT NULL,
    status VARCHAR(16) DEFAULT 'ACTIVE' NOT NULL,
    created_time DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    modify_time DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT uk_macau_catalog_code UNIQUE (poi_code),
    INDEX idx_macau_catalog_filter (region, category, status, valid_until)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

ALTER TABLE t_macau_catalog_poi
    MODIFY description_zh_hans VARCHAR(500) NOT NULL DEFAULT '',
    MODIFY description_zh_hant VARCHAR(500) NOT NULL DEFAULT '',
    MODIFY description_en VARCHAR(500) NOT NULL DEFAULT '',
    MODIFY description_pt VARCHAR(500) NOT NULL DEFAULT '',
    MODIFY opening_hours VARCHAR(128) NOT NULL DEFAULT 'Refer to official source',
    MODIFY source_organization VARCHAR(128) NOT NULL DEFAULT '澳门特别行政区政府旅游局',
    MODIFY source_url VARCHAR(500) NOT NULL DEFAULT 'https://www.macaotourism.gov.mo/';

ON DUPLICATE KEY UPDATE
region=VALUES(region),category=VALUES(category),name_zh_hans=VALUES(name_zh_hans),
name_zh_hant=VALUES(name_zh_hant),name_en=VALUES(name_en),name_pt=VALUES(name_pt),
longitude=VALUES(longitude),latitude=VALUES(latitude),opening_hours=VALUES(opening_hours),
accessibility_level=VALUES(accessibility_level),valid_until=VALUES(valid_until),
natural_merchant=VALUES(natural_merchant),status=VALUES(status);

UPDATE t_macau_catalog_poi SET
description_zh_hans=CONCAT(name_zh_hans,'，澳门公共文旅目录点位。'),
description_zh_hant=CONCAT(name_zh_hant,'，澳門公共文旅目錄點位。'),
description_en=CONCAT(name_en,', a point in the Macao public tourism catalogue.'),
description_pt=CONCAT(name_pt,', um ponto do catalogo publico de turismo de Macau.')
WHERE poi_code REGEXP '^[PTCL][0-9]{3}$';
